const staticData = $getWorkflowStaticData('global');
if (!staticData.knowledge_bases) staticData.knowledge_bases = [];
if (!staticData.kb_documents) staticData.kb_documents = [];
if (!staticData.next_kb_id) staticData.next_kb_id = 1;
if (!staticData.next_doc_id) staticData.next_doc_id = 1;

const input = $input.first().json;
const body = (input && typeof input.body === 'object' && input.body !== null) ? input.body : input;
const action = body.action || 'ping';

function now() { return new Date().toISOString(); }
let result = {};

switch (action) {
  case 'ping':
    result = { ok: true, message: 'KB Manager webhook reachable', received_at: now() };
    break;
  case 'create_kb': {
    const name = (body.name || '').trim();
    if (!name) { result = { error: 'KB name is required.' }; break; }
    const kb = { id: staticData.next_kb_id++, name, description: (body.description || '').trim(), created_at: now() };
    staticData.knowledge_bases.push(kb);
    result = { ok: true, knowledge_base: kb };
    break;
  }
  case 'list_kbs': {
    const kbs = staticData.knowledge_bases.map(kb => {
      const docCount = staticData.kb_documents.filter(d => d.kb_id === kb.id).length;
      return { ...kb, doc_count: docCount };
    });
    result = { knowledge_bases: kbs };
    break;
  }
  case 'delete_kb': {
    const kbId = parseInt(body.kb_id);
    if (!kbId) { result = { error: 'kb_id is required.' }; break; }
    const idx = staticData.knowledge_bases.findIndex(k => k.id === kbId);
    if (idx === -1) { result = { error: 'KB not found.' }; break; }
    staticData.knowledge_bases.splice(idx, 1);
    staticData.kb_documents = staticData.kb_documents.filter(d => d.kb_id !== kbId);
    result = { ok: true };
    break;
  }
  case 'upload_doc': {
    const kbId = parseInt(body.kb_id);
    if (!kbId) { result = { error: 'kb_id is required.' }; break; }
    const kb = staticData.knowledge_bases.find(k => k.id === kbId);
    if (!kb) { result = { error: 'KB not found.' }; break; }
    const filename = (body.filename || '').trim();
    if (!filename) { result = { error: 'filename is required.' }; break; }
    const content = (body.content || '').trim();
    if (!content) { result = { error: 'content is required.' }; break; }
    const docCount = staticData.kb_documents.filter(d => d.kb_id === kbId).length;
    if (docCount >= 20) { result = { error: 'Max 20 documents per KB.' }; break; }
    const doc = { id: staticData.next_doc_id++, kb_id: kbId, filename, content, file_size: parseInt(body.file_size) || content.length, uploaded_at: now() };
    staticData.kb_documents.push(doc);
    result = { ok: true, document: { id: doc.id, filename: doc.filename, file_size: doc.file_size } };
    break;
  }
  case 'list_docs': {
    const kbId = parseInt(body.kb_id);
    if (!kbId) { result = { error: 'kb_id is required.' }; break; }
    const docs = staticData.kb_documents.filter(d => d.kb_id === kbId).map(d => ({ id: d.id, filename: d.filename, file_size: d.file_size, uploaded_at: d.uploaded_at }));
    result = { documents: docs };
    break;
  }
  case 'delete_doc': {
    const kbId = parseInt(body.kb_id);
    const docId = parseInt(body.doc_id);
    if (!kbId || !docId) { result = { error: 'kb_id and doc_id are required.' }; break; }
    const idx = staticData.kb_documents.findIndex(d => d.id === docId && d.kb_id === kbId);
    if (idx === -1) { result = { error: 'Document not found.' }; break; }
    staticData.kb_documents.splice(idx, 1);
    result = { ok: true };
    break;
  }
  case 'get_content': {
    const kbId = parseInt(body.kb_id);
    if (!kbId) { result = { error: 'kb_id is required.' }; break; }
    const kb = staticData.knowledge_bases.find(k => k.id === kbId);
    if (!kb) { result = { error: 'KB not found.' }; break; }
    const docs = staticData.kb_documents.filter(d => d.kb_id === kbId);
    const text = docs.map(d => '## ' + d.filename + '\n\n' + d.content).join('\n\n---\n\n');
    result = { kb_id: kbId, kb_name: kb.name, content: text, doc_count: docs.length };
    break;
  }
  default:
    result = { error: 'Unknown action: ' + action };
}
return [{ json: result }];
